sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    const meisai_select = api.state.meisai_select;
    // console.log(meisai_select);
    const keys = Object.keys(meisai_select);

    if (keys != "") {
        keys.forEach(function(key) {
            console.log(">>>>>>>>>>>>>>>>" + meisai_select[key].cells.bikou.metadata.openRecordMetadata.sysId);
        });
        api.setState('ikkatu_hyouji', false);
    }else{
        api.setState('ikkatu_hyouji', true);
    }

}
